// f22 phdr reg addr end

#define _B2L32(data) ((((UINT32)(data&0xff000000) >> 24) & 0x000000ff) |   \
					(((UINT32)(data&0x00ff0000) >>  8) & 0x0000ff00) |   \
					(((UINT32)(data&0x0000ff00) <<  8) & 0x00ff0000) |   \
					(((UINT32)(data&0x000000ff) << 24) & 0xff000000))
#endif
											
#define BE_WCG_HW_O24_LUT_SECTION_SIZENUM (3*BE_WCG_HW_O24_LUT_SIZENUM) // 3 : R,G,B

#define BE_WCG_HW_O24_BLOCK_HDR(last, ai, mode, size) (((last) << 31) + ((ai) << 20) + ((mode)<<16) + (size))
#define BE_WCG_HW_O24_DATA_BLOCK_HDR_SIZE(r, g, b) (2 + 1 + (2*(((BE_WCG_HW_O24_LUT_COLUMN_SIZENUM - r)/2) + ((BE_WCG_HW_O24_LUT_COLUMN_SIZENUM - r)%2)) * \
					(((BE_WCG_HW_O24_LUT_COLUMN_SIZENUM - g)/2) + ((BE_WCG_HW_O24_LUT_COLUMN_SIZENUM - g)%2)) * \
					(((BE_WCG_HW_O24_LUT_COLUMN_SIZENUM - b)/2) + ((BE_WCG_HW_O24_LUT_COLUMN_SIZENUM - b)%2))))

/*----------------------------------------------------------------------------------------
	Type Definitions
----------------------------------------------------------------------------------------*/
typedef struct {
	struct delayed_work dlyWork;
	LX_BE_WCG_LUT_T lutParam;
} BE_WCG_HW_O24_DLY_3D_GAMUT_T;

typedef struct {
	struct delayed_work dlyWork;
	LX_BE_PQ_LUT_T lutParam;
} BE_PQ_HW_O24_DLY_LUMINENCE_BOOST_T;

typedef struct {
	LX_BE_LED_BPL_DATA_T bplData;
} BE_LED_HW_O24_SET_INFO_T;

typedef struct {
	UINT32	uWCGMode;
	UINT32	uWCGEn;
	BOOLEAN	uOAPLEn;
#ifdef BE_OVI_HW_O24_USE_VX1_CHIP_INFO
	UINT32 uLedSpiCtrlRegVal;
	void *pVx1ChipInfoVMapAddr;
	BE_OVI_HW_O24_VX1_CHIP_INFO_T *pVx1ChipInfo[BE_OVI_HW_O24_VX1_CHIP_INFO_MEM_BUFF_NUM];
#endif

	BE_WCG_HW_O24_DLY_3D_GAMUT_T delayed3DGamut;
	BE_PQ_HW_O24_DLY_LUMINENCE_BOOST_T delayedLumBoost;

	BE_LED_HW_O24_SET_INFO_T ledSetInfo;
	LX_OVI_HW_DISPLAY_INFO_T dispInfo;

	UINT32 pm_status;
	UINT32 pm_suspend;
} BE_LED_HW_O24_INFO_T;

typedef enum {
	BE_LED_MODE_OFF	= 0,
	BE_LED_MODE_LOW,
	BE_LED_MODE_MEDIUM,
	BE_LED_MODE_HIGH,
	BE_LED_MODE_HDR_LOW,
	BE_LED_MODE_HDR_MEDIUM,
	BE_LED_MODE_HDR_HIGH,
	BE_LED_MODE_HDR_PATTERN,
	BE_LED_MODE_RTINGS,
	BE_LED_MODE_LOWEST,
	BE_LED_MODE_MAX
} BE_LED_HW_O24_MODE_T;

