					BE_LED_REG_WR(0xCC862388, val); // REG_CCO_VERI_SYS_VERI_34_T
					//BE_ERROR("sat reg3 val 0x%x \n", val);

					//SICREQ-531 Add V4L2_CID_EXT_VPQ_LUMINANCE_BOOST_VERSION 0x60
