					BE_LED_REG_WR(0xCC460100, val); // REG_GSC_VERI_SYS_VERI_0_T

					val = ((UINT32)(lutData.phdr_sc_th_data[2] & 0x3FF) << 16) | (lutData.phdr_sc_th_data[3] & 0x3FF);
