					val = ((UINT32)(lutData.phdr_sc_th_data[6] & 0x3FF) << 16) | (lutData.phdr_rdf_data[0] & 0x3FF);
					BE_LED_REG_WR(0xCC46010C, val); // REG_GSC_VERI_SYS_VERI_3_T

					DECON_CTRL_O24_RdFL(reg_decon_ctrl_0);
